inline std::complex<double>
operator+(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) + rhs;
}
   template <typename T>
std::complex<T> operator*(int lhs, const std::complex<T>& rhs) {
   return static_cast<T>(lhs) * rhs;
}

inline double Csc(double x) {
return 1.0 / sin(x);
}

inline double Sec(double x) {
return 1.0 / cos(x);
}

inline double Cot(double x) {
return std::tan(M_PI_2 - x);
}





double DT::A1A1BbReal(const double&E3, const double&theta2, const double&theta1, const double&phi, const double&s)
{

double mb = MB;
double m1=MB;
double m2=MB;
double m3=0;
std::complex<double> mh1 = sqrt(std::complex<double>(MH*MH,-MH*WH));
std::complex<double> mh2 = sqrt(std::complex<double>(MS1*MS1,-MS1*WS1));
std::complex<double> MH1 = sqrt(std::complex<double>(MH*MH,-MH*WH));
std::complex<double> MH2 = sqrt(std::complex<double>(MS1*MS1,-MS1*WS1));
std::complex<double> MH1c = sqrt(std::complex<double>(MH*MH,MH*WH));
std::complex<double> MH2c = sqrt(std::complex<double>(MS1*MS1,MS1*WS1));

double v=vev;
double vs=svev;

double alphas = aS;


double m12 = sqrt(s - 2*E3*sqrt(s));
double lambda = sqrt(1- 4*mb*mb/(m12*m12));
double pre = 1/(64*pow(2*M_PI,4)) *sqrt(E3*E3)*sin(theta1)*sin(theta2)*lambda;


    double k1k2 =(-pow(m1,2) - pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s)/2.;
    double k1k3 =-0.5*((pow(m3,2) - E3*sqrt(s))*(pow(m1,2) - pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s) + sqrt((pow(E3,2) - pow(m3,2))/pow(E3 - sqrt(s),2))*(E3 - sqrt(s))*sqrt(s)*sqrt(pow(m1,4) + pow(-pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s,2) - 2*pow(m1,2)*(pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s))*cos(theta2))/(pow(m3,2) - 2*E3*sqrt(s) + s);
    double k2k3 =(-((pow(m3,2) - E3*sqrt(s))*(-pow(m1,2) + pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s)) + sqrt((pow(E3,2) - pow(m3,2))/pow(E3 - sqrt(s),2))*(E3 - sqrt(s))*sqrt(s)*sqrt(pow(m1,4) + pow(-pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s,2) - 2*pow(m1,2)*(pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s))*cos(theta2))/(2.*(pow(m3,2) - 2*E3*sqrt(s) + s));


    std::complex<double> restree =4*pow(EL,2.)*pow(MB,2.)*pow(k1k2 + k1k3 + k2k3 + pow(MB,2.),2.)*(MH1 - 1.*MH2)*(MH1 + MH2)*(MH1c - 1.*MH2c)*(MH1c + MH2c)*((k1k3*k2k3*(2.*pow(k1k2,2.) + 2.*k1k2*(k1k3 + k2k3) + pow(k1k3 + k2k3,2.)) - 1.*(k1k3 + k2k3)*(pow(k1k3,2.) + pow(k2k3,2.) + k1k2*(k1k3 + k2k3))*pow(MB,2.) + (pow(k1k3,2.) + pow(k2k3,2.))*pow(MB,4.))/(pow(k1k3,2.)*pow(k2k3,2.)*pow(2.*(k1k2 + k1k3 + k2k3) + 2.*pow(MB,2.) - 1.*pow(MH1,2.),1.)*pow(2.*(k1k2 + k1k3 + k2k3) + 2.*pow(MB,2.) - 1.*pow(MH1c,2.),1.)*pow(2.*(k1k2 + k1k3 + k2k3) + 2.*pow(MB,2.) - 1.*pow(MH2,2.),1.)*pow(2.*(k1k2 + k1k3 + k2k3) + 2.*pow(MB,2.) - 1.*pow(MH2c,2.),1.)) - (1.*(k1k2 + k1k3 + k2k3 - 1.*pow(MB,2.))*((2. + (2.*k1k2)/pow(k1k3 + k2k3,1.) - ((k1k3*(2.*k1k2 + k2k3) + (k1k2 + k2k3)*pow(MB,2.))*sqrt(4.*pow(k1k2 + k1k3 + k2k3,2.) - 4.*pow(MB,4.)))/(2.*pow(k1k3,1.)*pow(k1k2 + k1k3 + k2k3,1.)*sqrt(pow(k1k2 + k2k3,2.) - 2.*k1k3*pow(MB,2.) - 1.*pow(MB,4.))))/pow(k1k3,1.) + (2. + (2.*k1k2)/pow(k1k3 + k2k3,1.) - (((2.*k1k2 + k1k3)*k2k3 + (k1k2 + k1k3)*pow(MB,2.))*sqrt(4.*pow(k1k2 + k1k3 + k2k3,2.) - 4.*pow(MB,4.)))/(2.*pow(k2k3,1.)*pow(k1k2 + k1k3 + k2k3,1.)*sqrt(pow(k1k2 + k1k3,2.) - 2.*k2k3*pow(MB,2.) - 1.*pow(MB,4.))))/pow(k2k3,1.)))/(pow(-2.*(k1k2 + k1k3 + k2k3) - 2.*pow(MB,2.) + pow(MH1,2.),1.)*pow(-2.*(k1k2 + k1k3 + k2k3) - 2.*pow(MB,2.) + pow(MH1c,2.),1.)*pow(-2.*(k1k2 + k1k3 + k2k3) - 2.*pow(MB,2.) + pow(MH2,2.),1.)*pow(-2.*(k1k2 + k1k3 + k2k3) - 2.*pow(MB,2.) + pow(MH2c,2.),1.)))*pow(sin(2.*alpha),2.)/(3.*pow(v,2.)*pow(vs,2.));
    std::complex<double> qcdtree = (64*alphas*pow(MB,2)*pow(k1k2 + k1k3 + k2k3 + pow(MB,2),2)*(MH1 - MH2)*(MH1 + MH2)*(MH1c - MH2c)*(MH1c + MH2c)*((k1k3*k2k3*(2*pow(k1k2,2) + 2*k1k2*(k1k3 + k2k3) + pow(k1k3 + k2k3,2)) - (k1k3 + k2k3)*(pow(k1k3,2) + pow(k2k3,2) + k1k2*(k1k3 + k2k3))*pow(MB,2) + (pow(k1k3,2) + pow(k2k3,2))*pow(MB,4))/(pow(k1k3,2)*pow(k2k3,2)*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH1,2))*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH1c,2))*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH2,2))*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH2c,2))) - ((-k1k2 - k1k3 - k2k3 + pow(MB,2))*(-((2 + (2*k1k2)/(k1k3 + k2k3) - (sqrt((k1k2 + k1k3 + k2k3 - pow(MB,2))/(k1k2 + k1k3 + k2k3 + pow(MB,2)))*(k1k3*(2*k1k2 + k2k3) + (k1k2 + k2k3)*pow(MB,2)))/(k1k3*(k1k2 + k1k3 + k2k3)*sqrt((pow(k1k2 + k2k3,2) - 2*k1k3*pow(MB,2) - pow(MB,4))/pow(k1k2 + k1k3 + k2k3 + pow(MB,2),2))))/k1k3) - (2 + (2*k1k2)/(k1k3 + k2k3) - (sqrt((k1k2 + k1k3 + k2k3 - pow(MB,2))/(k1k2 + k1k3 + k2k3 + pow(MB,2)))*((2*k1k2 + k1k3)*k2k3 + (k1k2 + k1k3)*pow(MB,2)))/(k2k3*(k1k2 + k1k3 + k2k3)*sqrt((pow(k1k2 + k1k3,2) - 2*k2k3*pow(MB,2) - pow(MB,4))/pow(k1k2 + k1k3 + k2k3 + pow(MB,2),2))))/k2k3))/((-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH1,2))*(-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH1c,2))*(-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH2,2))*(-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH2c,2))))*Pi*pow(sin(2*alpha),2))/(pow(v,2)*pow(vs,2));
    
    
    double res =(restree).real()+qcdtree.real();
    return 1/(64.*pow(2*M_PI,4))*sqrt(E3*E3-m3*m3)*sin(theta2)*sin(theta1)*lambda*res;
    //1/(64.*pow(2*M_PI,4))*sqrt(E3*E3-m3*m3)*sin(theta2)*sin(theta1)*lambda*res;

}

double DT::A1A1BbRealQCD(const double&E3, const double&theta2, const double&theta1, const double&phi, const double&s)
{

double mb = MB;
double m1=MB;
double m2=MB;
double m3=0;
std::complex<double> mh1 = sqrt(std::complex<double>(MH*MH,-MH*WH));
std::complex<double> mh2 = sqrt(std::complex<double>(MS1*MS1,-MS1*WS1));
std::complex<double> MH1 = sqrt(std::complex<double>(MH*MH,-MH*WH));
std::complex<double> MH2 = sqrt(std::complex<double>(MS1*MS1,-MS1*WS1));
std::complex<double> MH1c = sqrt(std::complex<double>(MH*MH,MH*WH));
std::complex<double> MH2c = sqrt(std::complex<double>(MS1*MS1,MS1*WS1));

double v=vev;
double vs=svev;

double alphas = aS;

double m12 = sqrt(s - 2*E3*sqrt(s));
double lambda = sqrt(1- 4*mb*mb/(m12*m12));
double pre = 1/(64*pow(2*M_PI,4)) *sqrt(E3*E3)*sin(theta1)*sin(theta2)*lambda;


    double k1k2 =(-pow(m1,2) - pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s)/2.;
    double k1k3 =-0.5*((pow(m3,2) - E3*sqrt(s))*(pow(m1,2) - pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s) + sqrt((pow(E3,2) - pow(m3,2))/pow(E3 - sqrt(s),2))*(E3 - sqrt(s))*sqrt(s)*sqrt(pow(m1,4) + pow(-pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s,2) - 2*pow(m1,2)*(pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s))*cos(theta2))/(pow(m3,2) - 2*E3*sqrt(s) + s);
    double k2k3 =(-((pow(m3,2) - E3*sqrt(s))*(-pow(m1,2) + pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s)) + sqrt((pow(E3,2) - pow(m3,2))/pow(E3 - sqrt(s),2))*(E3 - sqrt(s))*sqrt(s)*sqrt(pow(m1,4) + pow(-pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s,2) - 2*pow(m1,2)*(pow(m2,2) + pow(m3,2) - 2*E3*sqrt(s) + s))*cos(theta2))/(2.*(pow(m3,2) - 2*E3*sqrt(s) + s));

    std::complex<double> qcdtree = (64*alphas*pow(MB,2)*pow(k1k2 + k1k3 + k2k3 + pow(MB,2),2)*(MH1 - MH2)*(MH1 + MH2)*(MH1c - MH2c)*(MH1c + MH2c)*((k1k3*k2k3*(2*pow(k1k2,2) + 2*k1k2*(k1k3 + k2k3) + pow(k1k3 + k2k3,2)) - (k1k3 + k2k3)*(pow(k1k3,2) + pow(k2k3,2) + k1k2*(k1k3 + k2k3))*pow(MB,2) + (pow(k1k3,2) + pow(k2k3,2))*pow(MB,4))/(pow(k1k3,2)*pow(k2k3,2)*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH1,2))*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH1c,2))*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH2,2))*(2*(k1k2 + k1k3 + k2k3) + 2*pow(MB,2) - pow(MH2c,2))) - ((-k1k2 - k1k3 - k2k3 + pow(MB,2))*(-((2 + (2*k1k2)/(k1k3 + k2k3) - (sqrt((k1k2 + k1k3 + k2k3 - pow(MB,2))/(k1k2 + k1k3 + k2k3 + pow(MB,2)))*(k1k3*(2*k1k2 + k2k3) + (k1k2 + k2k3)*pow(MB,2)))/(k1k3*(k1k2 + k1k3 + k2k3)*sqrt((pow(k1k2 + k2k3,2) - 2*k1k3*pow(MB,2) - pow(MB,4))/pow(k1k2 + k1k3 + k2k3 + pow(MB,2),2))))/k1k3) - (2 + (2*k1k2)/(k1k3 + k2k3) - (sqrt((k1k2 + k1k3 + k2k3 - pow(MB,2))/(k1k2 + k1k3 + k2k3 + pow(MB,2)))*((2*k1k2 + k1k3)*k2k3 + (k1k2 + k1k3)*pow(MB,2)))/(k2k3*(k1k2 + k1k3 + k2k3)*sqrt((pow(k1k2 + k1k3,2) - 2*k2k3*pow(MB,2) - pow(MB,4))/pow(k1k2 + k1k3 + k2k3 + pow(MB,2),2))))/k2k3))/((-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH1,2))*(-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH1c,2))*(-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH2,2))*(-2*(k1k2 + k1k3 + k2k3) - 2*pow(MB,2) + pow(MH2c,2))))*Pi*pow(sin(2*alpha),2))/(pow(v,2)*pow(vs,2));
    
    
    double res =qcdtree.real();
    return 1/(64.*pow(2*M_PI,4))*sqrt(E3*E3-m3*m3)*sin(theta2)*sin(theta1)*lambda*res;
}




std::complex<double> DT::A1A1BbTree(const double &cos_t, const double &s)
{
   std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return (MB*s*((MHSqcomp) - (MS1Sqcomp))*(s - 4*(MB*MB))*sin(2*alpha))/(svev*vev*(-s + (MHSqcomp))*(-s + (MS1Sqcomp)));
}

std::complex<double> DT::A1A1BbTreeConj(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return (MB*s*cos(alpha)*((conj(sqrt(MHSqcomp))*conj(sqrt(MHSqcomp))) - (conj(sqrt(MS1Sqcomp))*conj(sqrt(MS1Sqcomp))))*sin(alpha))/(svev*vev*(s - (conj(sqrt(MHSqcomp))*conj(sqrt(MHSqcomp))))*(s - (conj(sqrt(MS1Sqcomp))*conj(sqrt(MS1Sqcomp)))));
}

